package com.marketintel.service;
import com.marketintel.model.*; import org.springframework.stereotype.Service; import java.time.Instant; import java.util.*;
@Service public class PatternEngineService {
 public List<PatternSignal> detect(List<FeaturePoint> f){List<PatternSignal> out=new ArrayList<>();for(int i=2;i<f.size();i++){var a=f.get(i-2);var b=f.get(i-1);var c=f.get(i);if(a.close()>b.close()&&b.close()<c.close()&&c.close()>a.close()){out.add(new PatternSignal(c.symbol(),c.timestamp(),"DOUBLE_BOTTOM","BULLISH",.72,"Two-step local low with recovery above the first reference close."));}if(a.close()<b.close()&&b.close()>c.close()&&c.close()<a.close()){out.add(new PatternSignal(c.symbol(),c.timestamp(),"DOUBLE_TOP","BEARISH",.72,"Two-step local high with subsequent reversal."));}if(c.close()>c.sma20()&&b.close()<=b.sma20()){out.add(new PatternSignal(c.symbol(),c.timestamp(),"SMA20_BREAKOUT","BULLISH",.65,"Close crossed above the 20-period moving average."));}if(c.close()<c.sma20()&&b.close()>=b.sma20()){out.add(new PatternSignal(c.symbol(),c.timestamp(),"SMA20_BREAKDOWN","BEARISH",.65,"Close crossed below the 20-period moving average."));}if(c.rsi14()<30&&c.relativeVolume20()>1.2){out.add(new PatternSignal(c.symbol(),c.timestamp(),"OVERSOLD_VOLUME","BULLISH",.60,"RSI below 30 with elevated relative volume."));}if(c.rsi14()>70&&c.relativeVolume20()>1.2){out.add(new PatternSignal(c.symbol(),c.timestamp(),"OVERBOUGHT_VOLUME","BEARISH",.60,"RSI above 70 with elevated relative volume."));}}return out;}
}